(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var todos = [];
	var currentFilter = 'all';
	var localStorageKey = 'todos-vanillajs';

	function uuid() {
		return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
			var r = Math.random() * 16 | 0;
			var v = c === 'x' ? r : (r & 0x3 | 0x8);
			return v.toString(16);
		});
	}

	function loadTodos() {
		var stored = localStorage.getItem(localStorageKey);
		if (stored) {
			try {
				todos = JSON.parse(stored);
			} catch (e) {
				todos = [];
			}
		} else {
			todos = [];
		}
	}

	function saveTodos() {
		localStorage.setItem(localStorageKey, JSON.stringify(todos));
	}

	function getActiveTodos() {
		return todos.filter(function (todo) {
			return !todo.completed;
		});
	}

	function getCompletedTodos() {
		return todos.filter(function (todo) {
			return todo.completed;
		});
	}

	function getFilteredTodos() {
		switch (currentFilter) {
			case 'active':
				return getActiveTodos();
			case 'completed':
				return getCompletedTodos();
			default:
				return todos;
		}
	}

	function createTodoElement(todo) {
		var li = document.createElement('li');
		li.dataset.id = todo.id;

		if (todo.completed) {
			li.classList.add('completed');
		}

		var div = document.createElement('div');
		div.className = 'view';

		var checkbox = document.createElement('input');
		checkbox.className = 'toggle';
		checkbox.type = 'checkbox';
		checkbox.checked = todo.completed;

		var label = document.createElement('label');
		label.textContent = todo.title;

		var destroyButton = document.createElement('button');
		destroyButton.className = 'destroy';

		div.appendChild(checkbox);
		div.appendChild(label);
		div.appendChild(destroyButton);

		var editInput = document.createElement('input');
		editInput.className = 'edit';
		editInput.value = todo.title;

		li.appendChild(div);
		li.appendChild(editInput);

		return li;
	}

	function render() {
		var todoList = document.querySelector('.todo-list');
		var main = document.querySelector('.main');
		var footer = document.querySelector('.footer');
		var newTodoInput = document.querySelector('.new-todo');
		var toggleAll = document.querySelector('#toggle-all');
		var todoCount = document.querySelector('.todo-count');
		var clearCompleted = document.querySelector('.clear-completed');

		todoList.innerHTML = '';

		var filteredTodos = getFilteredTodos();
		filteredTodos.forEach(function (todo) {
			todoList.appendChild(createTodoElement(todo));
		});

		var activeTodos = getActiveTodos();
		var completedTodos = getCompletedTodos();
		var totalTodos = todos.length;

		if (totalTodos > 0) {
			main.style.display = '';
			footer.style.display = '';
		} else {
			main.style.display = 'none';
			footer.style.display = 'none';
		}

		toggleAll.checked = totalTodos > 0 && activeTodos.length === 0;

		var count = activeTodos.length;
		todoCount.innerHTML = '<strong>' + count + '</strong> ' + (count === 1 ? 'item' : 'items') + ' left';

		if (completedTodos.length > 0) {
			clearCompleted.style.display = '';
		} else {
			clearCompleted.style.display = 'none';
		}

		updateFilterLinks();
	}

	function updateFilterLinks() {
		var filterLinks = document.querySelectorAll('.filters a');
		filterLinks.forEach(function (link) {
			var filter = link.getAttribute('href').replace('#/', '') || 'all';
			if (filter === currentFilter) {
				link.classList.add('selected');
			} else {
				link.classList.remove('selected');
			}
