		todos = todos.map(function (todo) {
			if (todo.id === id) {
				return {
					id: todo.id,
					title: todo.title,
					completed: !todo.completed
				};
			}
			return todo;
		});

		saveTodos();
		render();
	}

	function toggleAll() {
		var activeTodos = getActiveTodos();
		var allCompleted = activeTodos.length === 0 && todos.length > 0;

		todos = todos.map(function (todo) {
			return {
				id: todo.id,
				title: todo.title,
				completed: !allCompleted
			};
		});

		saveTodos();
		render();
	}

	function deleteTodo(id) {
