  async loadApp() {
    const htmlPath = path.resolve(__dirname, '../../index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    const appJsPath = path.resolve(__dirname, '../../js/app.js');
    const appJs = fs.readFileSync(appJsPath, 'utf8');

    const baseCssPath = path.resolve(__dirname, '../../node_modules/todomvc-common/base.css');
    const baseCss = fs.existsSync(baseCssPath) ? fs.readFileSync(baseCssPath, 'utf8') : '';

    const appCssPath = path.resolve(__dirname, '../../css/app.css');
    const appCss = fs.existsSync(appCssPath) ? fs.readFileSync(appCssPath, 'utf8') : '';

    this.window = new Window({
      url: 'http://localhost/',
      pretendToBeVisual: true
    });

    this.document = this.window.document;

    // Inline the CSS and JS
    let modifiedHtml = html
      .replace(/<link rel="stylesheet" href="node_modules\/todomvc-common\/base\.css">/, `<style>${baseCss}</style>`)
      .replace(/<link rel="stylesheet" href="node_modules\/todomvc-app-css\/index\.css">/, '')
      .replace(/<link rel="stylesheet" href="css\/app\.css">/, `<style>${appCss}</style>`)
      .replace(/<script src="node_modules\/todomvc-common\/base\.js"><\/script>/, '')
      .replace(/<script src="js\/app\.js"><\/script>/, `<script>${appJs}</script>`);

    this.document.write(modifiedHtml);
    this.document.close();

    // Wait for script execution
    await new Promise(resolve => setTimeout(resolve, 100));
  }

