const { World, setWorldConstructor, Before } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

// Shared localStorage across reloads
let sharedLocalStorage = {};
// Preserve hash across reloads
let currentHash = '#/';

class TodoWorld extends World {
  constructor(parameters) {
    super(parameters);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    const htmlPath = path.resolve(__dirname, '../../index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    const appJsPath = path.resolve(__dirname, '../../js/app.js');
    const appJs = fs.readFileSync(appJsPath, 'utf8');

    this.window = new Window({
      url: 'http://localhost/' + currentHash.replace('#', ''),
      pretendToBeVisual: true
    });

    this.document = this.window.document;

    // Remove script tags and write HTML
    let modifiedHtml = html
      .replace(/<script src="node_modules\/todomvc-common\/base\.js"><\/script>/, '')
      .replace(/<script src="js\/app\.js"><\/script>/, '');

    this.document.write(modifiedHtml);
    this.document.close();

    // Mock localStorage to persist across reloads using Object.defineProperty
    const mockStorage = {
      getItem: function(key) {
        return sharedLocalStorage[key] || null;
      },
      setItem: function(key, value) {
        sharedLocalStorage[key] = String(value);
      },
      removeItem: function(key) {
        delete sharedLocalStorage[key];
      },
      clear: function() {
        sharedLocalStorage = {};
      },
      key: function(index) {
        return Object.keys(sharedLocalStorage)[index] || null;
      },
      get length() {
        return Object.keys(sharedLocalStorage).length;
      }
    };

    Object.defineProperty(this.window, 'localStorage', {
      value: mockStorage,
      writable: true,
      configurable: true
    });

    // Manually execute the app code
    const script = new Function('document', 'localStorage', 'window', appJs);
    script(this.document, this.window.localStorage, this.window);
  }

  async reloadApp() {
    await this.loadApp();
  }

  close() {
    if (this.window) {
      this.window.close();
    }
  }
}

// Reset shared localStorage and hash before each scenario
Before(function () {
  sharedLocalStorage = {};
  currentHash = '#/';
});

setWorldConstructor(TodoWorld);

